import { Color } from './colorize.ts';
import { getParentStackId } from './get-parent-stack-id.ts';
import type { PrintOpts, Range } from './grammar-graph-types.ts';
import type { GraphNode } from './graph-node.ts';
import type { GraphPointer } from './graph-pointer.ts';
import { isRange, isRuleChar, isRuleRef } from './type-guards.ts';

export const printGraphPointer =
  (pointer: GraphPointer) =>
  (opts: PrintOpts): string => {
    const col = opts.colorize;
    return col(`*${getParentStackId(pointer, col)}`, Color.RED);
  };

export const printGraphNode =
  (node: GraphNode) =>
  (opts: PrintOpts): string => {
    const { pointers, colorize: col, showPosition = false } = opts;
    const rule = node.rule;
    const parts: string[] = [];
    if (showPosition) {
      parts.push(
        col('{', Color.BLUE),
        col(node.id, Color.GRAY),
        col('}', Color.BLUE)
      );
    }

    if (isRuleChar(rule)) {
      parts.push(
        col('[', Color.GRAY),
        col(
          rule.value
            .map(value =>
              isRange(value)
                ? (value as Range)
                    .map(val => col(getChar(val), Color.YELLOW))
                    .join('')
                : getChar(value as number)
            )
            .join(''),
          Color.YELLOW
        ),
        col(']', Color.GRAY)
      );
    } else if (isRuleRef(rule)) {
      parts.push(
        col('Ref(', Color.GRAY),
        col(rule.value, Color.GREEN),
        col(')', Color.GRAY)
      );
    } else {
      parts.push(col(rule.type, Color.YELLOW));
    }

    if (pointers && pointers.size > 0) {
      for (const pointer of pointers) {
        const pointerParts: string[] = [];
        if (pointer.node === node) {
          pointerParts.push(pointer.print(opts));
        }

        if (pointerParts.length > 0) {
          parts.push(
            col('[', Color.GRAY),
            col(pointerParts.join(''), Color.YELLOW),
            col(']', Color.GRAY)
          );
        }
      }
    }

    const partsToReturn = [parts.join('')];
    if (node.next) {
      partsToReturn.push(node.next.print(opts));
    }

    return partsToReturn.join(col('-> ', Color.GRAY));
  };

export const getChar = (charCode: number): string => {
  const char = String.fromCodePoint(charCode);
  if (char === '\n') {
    return '\\n';
  }
  return char;
};
