    if is_rule_char_exclude(rule):
        return (
            f"{KEY_TRANSLATION[RuleType.CHAR_EXCLUDE]}-{_serialize_value(rule.value)}"
        )

    if is_rule_ref(rule):
        return f"{KEY_TRANSLATION[RuleType.REF]}-{rule.value}"

    raise ValueError(f"Unknown rule type: {rule!r}")

