import GBNF from '/workspace/reference_implementation/src/index.ts';
import { readFileSync, readdirSync } from 'node:fs';

const dir = '/workspace/tests/python/iteration/grammars';
const out: any[] = [];
for (const f of readdirSync(dir).filter(f => f.endsWith('.gbnf')).sort()) {
  const grammar = readFileSync(`${dir}/${f}`, 'utf8');
  const cases: string[] = JSON.parse(readFileSync(`${dir}/${f.replace(/\.gbnf$/, '.json')}`, 'utf8'));
  for (const c of cases.slice(0, 6)) {
    let state = GBNF(grammar);
    const steps: any[] = [[...state].map(r => [r.type, (r as any).value ?? null])];
    for (const ch of c) {
      state = state.add(ch);
      steps.push([...state].map(r => [r.type, (r as any).value ?? null]));
    }
    out.push({ f, c, steps });
  }
}
console.log(JSON.stringify(out));
EOF
